app.post('/api/auth/guest', authRateLimit, (req, res) => {
  const deviceId = getDeviceIdFromRequest(req);
  const deviceType = getDeviceTypeFromRequest(req);
  const controlType = getControlTypeFromRequest(req);
  if (!deviceId) {
    return res.status(400).json({ ok: false, error: 'Браузер не передал идентификатор гостевого профиля.' });
  }

  const login = guestLoginForDevice(deviceId);
  const deviceHash = guestDeviceHash(deviceId);
  let user = usersDb.users[login] || null;
  if (user && !guestUserMatchesDevice(user, deviceId)) {
    return res.status(409).json({ ok: false, error: 'Не удалось восстановить гостевой профиль этого браузера.' });
  }
  if (!user) {
    user = {
      id: makeUserId(),
      login,
      email: '',
      salt: '',
      passwordHash: '',
      isGuest: true,
      guestDeviceHash: deviceHash,
      createdAt: Date.now(),
      lastLoginAt: Date.now()
    };
    usersDb.users[login] = user;
  }

  const conflict = sessionConflictForLogin(login, deviceId);
  if (conflict) {
    return res.status(409).json({ ok: false, error: 'Гостевой профиль уже открыт в другой вкладке.' });
  }
  const token = createSession(login, user, deviceId, deviceType, controlType);
  clearAuthRateLimit(req);
  const characters = listUserCharacters(user);
  res.setHeader('Cache-Control', 'no-store');
  res.json({
    ok: true,
    token,
    user: {
      login,
      isGuest: true,
      displayName: guestDisplayNameForDevice(deviceId)
    },
    hasSave: characters.length > 0,
    characters
  });
});

app.post('/api/auth/register', authRateLimit, async (req, res, next) => {
  const login = normalizeLogin(req.body.login);
  const email = normalizeEmail(req.body.email);
  const password = String(req.body.password || '');
  const deviceId = getDeviceIdFromRequest(req);
  const deviceType = getDeviceTypeFromRequest(req);
  const controlType = getControlTypeFromRequest(req);
  if (!validateLogin(login)) {
    return res.status(400).json({ ok: false, error: 'Логин: 3–32 символа, латиница/цифры/._@-.' });
  }
  if (!validatePassword(password)) {
    return res.status(400).json({ ok: false, error: 'Пароль должен быть от 8 до 128 символов.' });
  }
  if (!validateEmail(email)) {
    return res.status(400).json({ ok: false, error: 'Введите корректный email для восстановления пароля.' });
  }
  if (usersDb.users[login]) {
    return res.status(409).json({ ok: false, error: 'Такой логин уже зарегистрирован.' });
  }
  if (userForEmail(email)) {
    return res.status(409).json({ ok: false, error: 'Этот email уже используется другим аккаунтом.' });
  }
  let passwordRecord;
  try {
    passwordRecord = await passwordHasher.hashPassword(password);
  } catch (error) {
    if (isPasswordHashBusyError(error)) return passwordHashBusyResponse(res);
    return next(error);
  }
  // The asynchronous hash leaves a small race window. Recheck both unique
  // constraints before committing the new account.
  if (usersDb.users[login]) {
    return res.status(409).json({ ok: false, error: 'Такой логин уже зарегистрирован.' });
  }
  if (userForEmail(email)) {
    return res.status(409).json({ ok: false, error: 'Этот email уже используется другим аккаунтом.' });
  }
  const user = {
    id: makeUserId(),
    login,
    email,
    salt: passwordRecord.salt,
    passwordHash: passwordRecord.hash,
    createdAt: Date.now(),
    lastLoginAt: Date.now()
  };
  usersDb.users[login] = user;
  const token = createSession(login, user, deviceId, deviceType, controlType);
  clearAuthRateLimit(req);
  res.json({ ok: true, token, user: { login, email }, hasSave: false, characters: [] });
});

app.post('/api/auth/login', authRateLimit, async (req, res, next) => {
  const login = normalizeLogin(req.body.login);
  const password = String(req.body.password || '');
  const deviceId = getDeviceIdFromRequest(req);
  const deviceType = getDeviceTypeFromRequest(req);
  const controlType = getControlTypeFromRequest(req);
  const user = usersDb.users[login] || null;
  const passwordSnapshot = user
    ? { salt: String(user.salt || ''), passwordHash: String(user.passwordHash || '') }
    : DUMMY_PASSWORD_RECORD;
  let passwordValid = false;
  try {
    passwordValid = await passwordHasher.verifyPassword(password, passwordSnapshot);
  } catch (error) {
    if (isPasswordHashBusyError(error)) return passwordHashBusyResponse(res);
    return next(error);
  }
  if (!user
    || usersDb.users[login] !== user
    || String(user.salt || '') !== passwordSnapshot.salt
    || String(user.passwordHash || '') !== passwordSnapshot.passwordHash
    || !passwordValid) {
    return res.status(401).json({ ok: false, error: 'Неверный логин или пароль.' });
  }
  const conflict = sessionConflictForLogin(login, deviceId);
  if (conflict) {
    return res.status(409).json({ ok: false, error: 'Этот аккаунт уже открыт на другом устройстве. Выйдите там из игры или подождите около минуты после закрытия вкладки.' });
  }
  const token = createSession(login, user, deviceId, deviceType, controlType);
  clearAuthRateLimit(req);
  const characters = listUserCharacters(user, login);
  res.json({ ok: true, token, user: { login }, hasSave: characters.length > 0, characters });
});

app.post('/api/auth/password-reset/request', authRateLimit, async (req, res) => {
  const email = normalizeEmail(req.body.email);
  if (!validateEmail(email)) {
    return res.status(400).json({ ok: false, error: 'Введите корректный email.' });
  }
  const user = userForEmail(email);
  if (user) {
    const token = crypto.randomBytes(32).toString('hex');
    user.passwordReset = createPasswordResetRecord(token, PASSWORD_RESET_TTL_MS);
    persistUsers();
    try {
      await sendPasswordResetEmail(user, token);
    } catch (err) {
      delete user.passwordReset;
      persistUsers();
      console.error('Password reset email failed:', err.message);
      return res.status(503).json({ ok: false, error: 'Отправка писем временно недоступна. Обратитесь к администратору.' });
    }
  }
  clearAuthRateLimit(req);
  res.json({ ok: true, message: 'Если этот email зарегистрирован, ссылка для восстановления отправлена.' });
});

app.post('/api/auth/password-reset/confirm', authRateLimit, async (req, res, next) => {
  const login = normalizeLogin(req.body.login);
  const token = String(req.body.token || '').trim();
  const password = String(req.body.password || '');
  const user = usersDb.users[login];
  const reset = user?.passwordReset;
  if (!validatePassword(password)) {
    return res.status(400).json({ ok: false, error: 'Пароль должен быть от 8 до 128 символов.' });
  }
  const storedHash = String(reset?.tokenHash || '');
  if (!user || !passwordResetRecordIsValid(reset, token)) {
    return res.status(400).json({ ok: false, error: 'Ссылка восстановления недействительна или устарела.' });
  }
  let passwordRecord;
  try {
    passwordRecord = await passwordHasher.hashPassword(password);
  } catch (error) {
    if (isPasswordHashBusyError(error)) return passwordHashBusyResponse(res);
    return next(error);
  }
  const currentReset = user.passwordReset;
  const resetStillValid = usersDb.users[login] === user
    && currentReset === reset
    && Number(currentReset?.expiresAt || 0) >= Date.now()
    && String(currentReset?.tokenHash || '') === storedHash;
  if (!resetStillValid) {
    return res.status(400).json({ ok: false, error: 'Ссылка восстановления недействительна или устарела.' });
  }
  user.salt = passwordRecord.salt;
  user.passwordHash = passwordRecord.hash;
  user.passwordChangedAt = Date.now();
  delete user.passwordReset;
  for (const [sessionToken, session] of Object.entries(usersDb.sessions || {})) {
    if (session?.login === login) delete usersDb.sessions[sessionToken];
  }
  persistUsers();
  clearAuthRateLimit(req);
  res.json({ ok: true, message: 'Пароль изменён. Теперь можно войти.' });
});

