function serverApprovedActorModelKey(modelKey = '') {
  const key = String(modelKey || '').trim();
  return SERVER_APPROVED_ACTOR_MODEL_KEYS.has(key) ? key : '';
}

function serverModelFileForRef(modelRef = '') {
  const key = String(modelRef || '').trim();
  return SERVER_MODEL_FILE_BY_KEY[key] || key;
}

function serverEnemyModelKeyForVisual(visual = '') {
  const raw = String(visual || '').trim();
  if (!raw) return '';
  const key = raw.replace(/[^a-zA-Z0-9_]+/g, '').toLowerCase();
  const snake = raw.replace(/([a-z0-9])([A-Z])/g, '$1_$2').replace(/[^a-zA-Z0-9_]+/g, '_').replace(/^_+|_+$/g, '').toLowerCase();
  return serverApprovedActorModelKey(SERVER_ENEMY_MODEL_KEY_BY_VISUAL[key] || SERVER_ENEMY_MODEL_KEY_BY_VISUAL[snake]);
}

function serverModelKeyForExplicitRef(modelRef = '') {
  const raw = String(modelRef || '').trim();
  if (!raw) return '';
  const explicit = raw.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64);
  const legacyCreatureModelAliases = {
    enemyGhoul: 'kromkaBurned',
    enemySuperMutant: 'kromkaFold',
    enemyAshWolf: 'kromkaGari',
    enemyRadscorpion: 'kromkaRykhlyak',
    enemyMutantAnt: 'kromkaDustling',
    enemyGecko: 'kromkaListener',
    enemyFireGecko: 'kromkaMourner'
  };
  if (legacyCreatureModelAliases[explicit]) return legacyCreatureModelAliases[explicit];
  const explicitAlias = serverEnemyModelKeyForVisual(explicit);
  if (explicitAlias) return explicitAlias;
  const explicitActorKey = serverApprovedActorModelKey(explicit);
  if (explicitActorKey) return explicitActorKey;

  let decoded = raw;
  try { decoded = decodeURIComponent(raw); } catch (_) {}
  const pathOnly = decoded.split(/[?#]/, 1)[0].replace(/\\/g, '/');
  const filename = String(pathOnly.split('/').pop() || '').toLowerCase();
  const fileModelKey = serverApprovedActorModelKey(SERVER_MODEL_KEY_BY_FILE[filename]);
  return legacyCreatureModelAliases[fileModelKey] || fileModelKey;
}

function serverEnemyModelKeyForIdentity(actor = {}, fallbackVisual = '') {
  for (const explicitRef of [actor?.modelKey, actor?.model]) {
    const explicitModelKey = serverModelKeyForExplicitRef(explicitRef);
    if (explicitModelKey) return explicitModelKey;
  }

  const candidates = [
    actor?.visual,
    actor?.species,
    actor?.lootTier,
    actor?.profile,
    actor?.statProfile,
    actor?.equipmentProfile,
    actor?.lootProfile,
    fallbackVisual
  ];
  for (const candidate of candidates) {
    const modelKey = serverEnemyModelKeyForVisual(candidate);
    if (modelKey) return modelKey;
  }

  const text = [
    actor?.name,
    actor?.typeName,
    actor?.visual,
    actor?.species,
    actor?.role,
    actor?.encounterRole,
    ...candidates
  ].map(value => String(value || '')).join(' ').toLowerCase();
  const compact = text.replace(/[^a-z0-9]+/g, '');
  const role = String(actor?.role || actor?.encounterRole || '').trim().toLowerCase();
  const faction = String(actor?.faction || '').trim().toLowerCase();
  if (role === 'merchant' || role === 'trader') return 'caravanMerchant';
  if (role === 'guard') {
    if (faction === 'old_klim' || faction === 'klim_patrol' || compact.includes('klim') || text.includes('клим')) return 'klimPatrolGuard';
    return 'caravanGuard';
  }
  if (role === 'civilian' || role === 'settler' || role === 'worker') return 'wastelandSettler';
  if (compact.includes('firegecko') || (text.includes('огнен') && text.includes('геккон'))) return 'kromkaMourner';
  if (compact.includes('radscorpion') || text.includes('скорпион')) return 'kromkaRykhlyak';
  if (compact.includes('mutantant') || text.includes('мурав')) return 'kromkaDustling';
  if (compact.includes('ashwolf') || text.includes('wolf') || text.includes('волк')) return 'kromkaGari';
  if (compact.includes('brahmin') || text.includes('брамин') || role === 'animal') return 'friendlyBrahmin';
  if (compact.includes('supermutant') || text.includes('супермутант')) return 'kromkaFold';
  if (compact.includes('ghoul') || text.includes('гул')) return 'kromkaBurned';
  if (compact.includes('gecko') || text.includes('геккон')) return 'kromkaListener';
  if (compact.includes('raider') || text.includes('рейдер') || role === 'raider') return 'enemyRaider';
  return '';
}

function serverEnemyModelKeyForType(type = {}, fallbackVisual = '') {
  return serverEnemyModelKeyForIdentity(type, fallbackVisual);
}

const SERVER_ENEMY_FACTION_BY_LOOT_TIER = {
  raider: 'raiders',
  ghoul: 'ghouls',
  superMutant: 'super_mutants',
  ashWolf: 'ash_wolves',
  radScorpion: 'radscorpions',
  mutantAnt: 'mutant_ants',
  gecko: 'geckos',
  fireGecko: 'geckos'
};
const SERVER_FACTION_ALLIES = new Set([
  'tract_league|uprava',
  'uprava|tract_league'
]);
const SERVER_JOINABLE_WORLD_FACTIONS = new Set([
  'uprava', 'free_artels', 'contour', 'tract_league', 'seconds', 'continuity'
]);
const SERVER_DEFAULT_FACTION_RELATIONS = {
  uprava: { free_artels: -20, contour: 45, tract_league: 25, seconds: -35, continuity: 10 },
  free_artels: { uprava: -20, contour: -10, tract_league: 40, seconds: 30, continuity: -45 },
  contour: { uprava: 45, free_artels: -10, tract_league: 20, seconds: -15, continuity: 35 },
  tract_league: { uprava: 25, free_artels: 40, contour: 20, seconds: 15, continuity: 5 },
  seconds: { uprava: -35, free_artels: 30, contour: -15, tract_league: 15, continuity: -70 },
  continuity: { uprava: 10, free_artels: -45, contour: 35, tract_league: 5, seconds: -70 }
};

function serverFactionKey(faction = '') {
  return String(faction || 'wild').toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 32) || 'wild';
}

function serverWorldFactionKey(faction = '') {
  return canonicalKromkaFactionId(serverFactionKey(faction));
}

function sanitizeServerWorldFactionReputation(input = {}) {
  return sanitizeKromkaReputation(input);
}

const SERVER_PLAYER_FACTION_MODEL_VERSION = PLAYER_FACTION_MODEL_VERSION;

function sanitizeServerFactionContracts(input = {}, now = Date.now()) {
  return sanitizeKromkaContracts(input, now);
}

function sanitizePersistedPlayerFactionState(state = {}) {
  return migrateKromkaPlayerFactionState(state);
}

function migrateStoredPlayerFactionModel() {
  let changed = 0;
  for (const store of Object.values(savesDb.characters || {})) {
    for (const row of Object.values(store || {})) {
      if (!row?.state || typeof row.state !== 'object') continue;
      const before = JSON.stringify({
        profile: row.state.characterProfile,
        reputation: row.state.worldFactionReputation,
        archived: row.state.archivedWorldFactionReputation,
        version: row.state.worldFactionModelVersion,
        summaryFactionId: row.summary?.factionId,
        summaryFactionName: row.summary?.factionName
      });
      sanitizePersistedPlayerFactionState(row.state);
      if (row.summary && typeof row.summary === 'object') {
        row.summary.factionId = serverWorldFactionKey(
          row.state.characterProfile?.worldFactionId || row.state.characterProfile?.factionId || ''
        );
        if (!row.summary.factionId) delete row.summary.factionName;
      }
      const after = JSON.stringify({
        profile: row.state.characterProfile,
        reputation: row.state.worldFactionReputation,
        archived: row.state.archivedWorldFactionReputation,
        version: row.state.worldFactionModelVersion,
        summaryFactionId: row.summary?.factionId,
        summaryFactionName: row.summary?.factionName
      });
      if (before !== after) changed += 1;
    }
  }
  if (changed > 0) persistSaves();
  return changed;
}

migrateStoredPlayerFactionModel();

const SERVER_ALWAYS_HOSTILE_FACTION_GROUPS = new Set([
  'raiders',
  'skladni',
  'gari',
  'rykhlyaki',
  'slukhachi',
  'plakalshchiki',
  'pylniki',
  'mutants',
  'ghouls',
  'radscorpions',
  'mutant_ants',
  'geckos',
  'ash_wolves',
  'monsters',
  'wild'
]);

const SERVER_WILD_FACTION_GROUPS = new Set([
  'skladni',
  'gari',
  'rykhlyaki',
  'slukhachi',
  'plakalshchiki',
  'fonarniki',
  'pylniki',
  'ghouls',
  'radscorpions',
  'mutant_ants',
  'geckos',
  'ash_wolves',
  'monsters',
  'wild'
]);

function serverCombatFactionGroup(faction = '') {
  const key = serverFactionKey(faction);
  if (!key || key === 'neutral') return key || 'neutral';
  if (key === 'caravan' || key === 'caravans' || key === 'tract_league') return 'tract_league';
  if (key === 'klim_patrol' || key === 'old_klim' || key === 'uprava') return 'uprava';
  if (key === 'scrap' || key === 'scrap_town' || key === 'scrap_union' || key === 'free_artels') return 'free_artels';
  if (key === 'relay' || key === 'relay_station' || key === 'relay_order' || key === 'contour') return 'contour';
  if (key === 'raider' || key === 'raiders') return 'raiders';
  if (key === 'super_mutant' || key === 'super_mutants' || key === 'mutant' || key === 'mutants') return 'mutants';
  if (key === 'ghoul' || key === 'ghouls') return 'ghouls';
  if (key === 'radscorpion' || key === 'radscorpions') return 'radscorpions';
  if (key === 'mutant_ant' || key === 'mutant_ants' || key === 'ant' || key === 'ants') return 'mutant_ants';
  if (key === 'gecko' || key === 'geckos' || key === 'firegecko' || key === 'fire_gecko') return 'geckos';
  if (key === 'ash_wolf' || key === 'ash_wolves') return 'ash_wolves';
  if (key === 'monster' || key === 'monsters') return 'monsters';
  return key;
}

function serverGlobalMapBounds() {
  const grid = GLOBAL_MAP?.grid || GLOBAL_MAP_GRID_DEFAULT;
  const cols = clamp(Math.round(Number(grid.cols || GLOBAL_MAP_GRID_DEFAULT.cols)), 4, 80);
  const rows = clamp(Math.round(Number(grid.rows || GLOBAL_MAP_GRID_DEFAULT.rows)), 4, 80);
  const cellPoints = clamp(Math.round(Number(grid.cellPoints || GLOBAL_MAP_GRID_DEFAULT.cellPoints)), 4, 200);
  return { width: cols * cellPoints, height: rows * cellPoints };
}

function sanitizeServerGlobalMapPoint(input = null) {
  if (!input || typeof input !== 'object') return null;
  const x = Number(input.x ?? input.playerX ?? input.worldX);
  const y = Number(input.y ?? input.playerY ?? input.worldY);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  const bounds = serverGlobalMapBounds();
  return {
    x: Math.max(0, Math.min(bounds.width, x)),
    y: Math.max(0, Math.min(bounds.height, y))
  };
}

function serverDefaultFactionForEnemyType(type = {}, opts = {}) {
  if (opts.faction) return serverFactionKey(opts.faction);
  if (opts.role === 'guard' || opts.role === 'merchant') return 'neutral';
  if (type.creatureTypeId && type.faction) return serverFactionKey(type.faction);
  return SERVER_ENEMY_FACTION_BY_LOOT_TIER[type.lootTier] || 'wild';
}

function serverFactionsHostile(a = null, b = null) {
  const left = serverCombatFactionGroup(typeof a === 'string' ? a : a?.faction);
  const right = serverCombatFactionGroup(typeof b === 'string' ? b : b?.faction);
  if (!left || !right || left === right) return false;
  if (left === 'neutral' || right === 'neutral') return false;
  if (SERVER_FACTION_ALLIES.has(`${left}|${right}`)) return false;
  if (left === 'raiders' || right === 'raiders') return true;
  if (left === 'mutants' || right === 'mutants') return true;
  if (SERVER_WILD_FACTION_GROUPS.has(left) || SERVER_WILD_FACTION_GROUPS.has(right)) return true;
  return serverFactionRelation(left, right) <= -35 || serverFactionRelation(right, left) <= -35;
}

function serverActorDefaultHostileToPlayer(actor = null) {
  if (!actor) return false;
  if (actor.hostileToPlayer === true) return true;
  if (actor.hostileToPlayer === false) return false;
  const actorGroup = serverCombatFactionGroup(actor.faction || '');
  if (!actorGroup || actorGroup === 'neutral') return false;
  return SERVER_ALWAYS_HOSTILE_FACTION_GROUPS.has(actorGroup);
}

function serverFactionRelation(a = '', b = '') {
  const left = serverCombatFactionGroup(a);
  const right = serverCombatFactionGroup(b);
  if (!left || !right) return 0;
  if (left === right) return 100;
  try {
    const simState = WASTELAND_SIM && typeof WASTELAND_SIM.state === 'function' ? WASTELAND_SIM.state() : null;
    const rel = Number(simState?.factions?.[left]?.relations?.[right]);
    if (Number.isFinite(rel)) return rel;
  } catch (_) {
    // During early module initialization WASTELAND_SIM is not available yet.
  }
  const fallback = Number(SERVER_DEFAULT_FACTION_RELATIONS[left]?.[right]);
  return Number.isFinite(fallback) ? fallback : 0;
}

function serverActorHostileToPlayer(actor = null, player = null) {
  if (!actor || !player || actor.dead || player.dead || Number(player.hp || 0) <= 0) return false;
  if (locationIsFactionCapital(player.locationId || player.currentLocationId || '')) return false;
  // Гарнизон и охрана Сердцевины: враждебны игрокам других фракций территории
  // и дружественны своим независимо от канонических отношений сторон.
  const actorTerritoryFaction = String(actor.territoryFactionId || '');
  if (actorTerritoryFaction) {
    const playerTerritoryFaction = serverPlayerTerritoryFactionId(player);
    if (playerTerritoryFaction && playerTerritoryFaction !== actorTerritoryFaction) return true;
    if (playerTerritoryFaction === actorTerritoryFaction) return false;
  }
  if (actorIsExplicitlyHostileToPlayer(actor, player)) return true;
  const actorGroup = serverCombatFactionGroup(actor.faction || '');
  if (!actorGroup || actorGroup === 'neutral') return false;
  if (actor.hostileToPlayer === true) return true;
  if (SERVER_ALWAYS_HOSTILE_FACTION_GROUPS.has(actorGroup)) return true;
  const playerFaction = serverWorldFactionKey(player.worldFactionId || player.factionId || player.playerFactionId || '');
  if (!playerFaction) return false;
  const playerGroup = serverCombatFactionGroup(playerFaction);
  if (!playerGroup || playerGroup === actorGroup) return false;
  return serverFactionsHostile(actorGroup, playerGroup);
}

function serverCombatFactionsAllied(leftFaction = '', rightFaction = '') {
  if (!leftFaction || !rightFaction) return false;
  const left = serverCombatFactionGroup(leftFaction);
  const right = serverCombatFactionGroup(rightFaction);
  return left === right || SERVER_FACTION_ALLIES.has(`${left}|${right}`);
}

function serverPlayersAllied(attacker = {}, target = {}) {
  const left = sanitizeServerSocialState(attacker.socialState || {});
  const right = sanitizeServerSocialState(target.socialState || {});
  if (left.clan.id && left.clan.id === right.clan.id) return true;
  if (left.friends.some(row => row.id === (target.characterId || target.id))
    || right.friends.some(row => row.id === (attacker.characterId || attacker.id))) return true;
  if (serverCombatFactionsAllied(
    serverWorldFactionKey(attacker.worldFactionId || attacker.factionId || ''),
    serverWorldFactionKey(target.worldFactionId || target.factionId || '')
  )) return true;
  const attachment = serverWorldPartyAttachmentForPlayer(attacker);
  return !!attachment && (attachment.party.playerMembers || [])
    .some(member => playerMatchesWorldPartyMember(target, member));
}

function serverPlayerCanDamageNpc(player, enemy, room) {
  if (!enemy || enemy.dead || !roomAllowsNpcCombat(room)
    || serverNpcIsKromkaOnboardingProtected(enemy)
    || !serverActorHostileToPlayer(enemy, player)) return false;
  if (serverCombatFactionsAllied(
    serverWorldFactionKey(player.worldFactionId || player.factionId || ''), enemy.faction
  )) return false;
  const attachment = serverWorldPartyAttachmentForPlayer(player);
  if (attachment && (enemy.onsitePartyId === attachment.party.id
    || (room.worldPartyId === attachment.party.id && enemy.encounterRole === 'guard'))) return false;
  return true;
}

// Поселение для возрождения/возврата с учётом доступа к базам фракций.
function serverAccessibleSettlementId(locationId = '', membership = null) {
  const candidate = normalizeRespawnSettlementId(locationId || 'settlement');
  if (territoryLocationAccess(LOCATIONS[candidate] || {}, membership, KROMKA_TERRITORY_CATALOG).allowed) return candidate;
  return normalizeRespawnSettlementId('settlement');
}

function serverPlayerTerritoryFactionId(player = {}) {
  return String(player?.territoryFaction?.factionId || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32);
}

function serverRoomTerritoryId(room = null) {
  return String(roomLocation(room)?.territoryId || '').slice(0, 32);
}

function serverTerritoryPlatformZoneAt(room = null, x = 0, z = 0) {
  const loc = roomLocation(room);
  if (!loc?.territoryId || !Array.isArray(loc.worldZones)) return null;
  const dims = locationTileDims(loc);
  for (const zone of loc.worldZones) {
    if (String(zone?.type || '') !== 'factionPlatform') continue;
    const center = tileToWorld(Number(zone.tx || 0), Number(zone.tz || 0), dims);
    if (Math.hypot(Number(x || 0) - center.x, Number(z || 0) - center.z) <= Number(zone.radius || 0)) return zone;
  }
  return null;
}

function serverTerritoryPlayerInCombat(player = {}, now = Date.now(), graceMs = KROMKA_TERRITORY_COMBAT_GRACE_MS) {
  return now - Number(player?.lastServerDamageAt || 0) < graceMs
    || now - Number(player?.serverCombat?.lastAttackAt || 0) < graceMs;
}

// Правила PvP Сердцевины: своя фракция не наносит урон своим, с платформы
// нельзя атаковать, а игрок на платформе своей фракции защищён после паузы
// без боя (бой нельзя прервать мгновенно, забежав на платформу).
function serverTerritoryPvpBlock(attacker = {}, target = {}, room = null, now = Date.now()) {
  if (!serverRoomTerritoryId(room)) return '';
  const attackerFaction = serverPlayerTerritoryFactionId(attacker);
  const targetFaction = serverPlayerTerritoryFactionId(target);
  if (attackerFaction && attackerFaction === targetFaction) return 'sameFaction';
  if (serverTerritoryPlatformZoneAt(room, attacker.x, attacker.z)) return 'attackerOnPlatform';
  const targetPlatform = serverTerritoryPlatformZoneAt(room, target.x, target.z);
  if (targetPlatform && String(targetPlatform.factionId || '') === targetFaction
    && !serverTerritoryPlayerInCombat(target, now)) return 'targetProtected';
  return '';
}

function serverZoneRulesExtra(loc = null) {
  if (!loc || typeof loc !== 'object') return {};
  const territoryId = String(loc.territoryId || '');
  if (!territoryId) return {};
  const factionAccess = String(loc.factionAccess || 'territory');
  return {
    access: factionAccess === 'territory' ? 'faction' : 'ownFaction',
    territoryId,
    factionId: factionAccess === 'territory' ? '' : factionAccess,
    factionPvp: true,
    title: String(loc.name || '')
  };
}

function serverNearbyServiceActor(player = {}, service = '', range = 5.2) {
  const room = rooms.get(String(player?.roomId || ''));
  if (!room || !(room.enemies instanceof Map)) return null;
  for (const actor of room.enemies.values()) {
    if (!actor || actor.dead || actor.hostileToPlayer !== false) continue;
    if (String(actor.service || '') !== String(service || '')) continue;
    if (Math.hypot(Number(player.x || 0) - Number(actor.x || 0), Number(player.z || 0) - Number(actor.z || 0)) > range) continue;
    if (!serverInteractionHasLineOfSight(room, player, actor)) continue;
    return actor;
  }
  return null;
}

function publicTerritoryCatalog() {
  const catalog = KROMKA_TERRITORY_CATALOG || {};
  return {
    id: String(catalog.id || 'core'),
    displayName: String(catalog.displayName || 'Сердцевина'),
    zoneLocationId: String(catalog.zoneLocationId || 'coreZone'),
    factions: (Array.isArray(catalog.factions) ? catalog.factions : []).map(row => ({
      id: String(row.id || ''),
      baseLocationId: String(row.baseLocationId || ''),
      baseDisplayName: String(row.baseDisplayName || ''),
      capitalLocationId: String(row.capitalLocationId || ''),
      platformEntryKey: String(row.platform?.entryKey || '')
    })),
    rules: {
      factionChangeCooldownMs: Number(catalog.rules?.factionChangeCooldownMs || 0),
      combatExitGraceMs: KROMKA_TERRITORY_COMBAT_GRACE_MS,
      joinRequiresReputation: Number(catalog.rules?.joinRequiresReputation || 0)
    }
  };
}

// --- Контракт наёмника на входе в Сердцевину -------------------------------
// Узел Сердцевины на глобальной карте работает как ворота территории: игрок
// или группа приходит туда, подписывает контракт с фракцией и попадает на её
// базу. Метки самих баз на карте скрыты, отдельными точками входа они больше
// не являются.

const TERRITORY_FACTION_SHARES_TTL_MS = 15000;
let territoryFactionSharesCache = { at: 0, value: null };

function serverTerritoryZoneLocationId() {
  return normalizeLocationId(String(KROMKA_TERRITORY_CATALOG?.zoneLocationId || 'coreZone'));
}

function serverIsTerritoryGateLocation(locationId = '') {
  const id = normalizeLocationId(locationId);
  return !!id && id === serverTerritoryZoneLocationId();
}

function serverTerritoryFactionNames() {
  const names = {};
  for (const row of Array.isArray(KROMKA_FACTION_CATALOG?.factions) ? KROMKA_FACTION_CATALOG.factions : []) {
    const id = String(row?.id || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32);
    if (id) names[id] = String(row?.displayName || row?.name || id);
  }
  return names;
}

function invalidateTerritoryFactionSharesCache() {
  territoryFactionSharesCache = { at: 0, value: null };
}

/**
 * Доли фракций по всем сохранённым персонажам. Пересчёт стоит обхода всех
 * сохранений, поэтому результат живёт несколько секунд и сбрасывается при
 * смене принадлежности.
 */
function serverTerritoryFactionShares(now = Date.now()) {
  if (territoryFactionSharesCache.value && now - territoryFactionSharesCache.at < TERRITORY_FACTION_SHARES_TTL_MS) {
    return territoryFactionSharesCache.value;
  }
  const memberships = [];
  for (const store of Object.values(savesDb.characters || {})) {
    for (const row of Object.values(store || {})) {
      memberships.push(row?.state?.territoryFaction || null);
    }
  }
  const value = territoryFactionShares(memberships, KROMKA_TERRITORY_CATALOG);
  territoryFactionSharesCache = { at: now, value };
  return value;
}

function serverTerritoryContractOffer(player = null, now = Date.now()) {
  return territoryContractOffer({
    catalog: KROMKA_TERRITORY_CATALOG,
    factionNames: serverTerritoryFactionNames(),
    membership: player?.territoryFaction,
    shares: serverTerritoryFactionShares(now),
    reputation: sanitizeServerWorldFactionReputation(player?.worldFactionReputation || {}),
    now
  });
}

/**
 * Куда сервер заводит прибывшего к воротам территории. Без подписанного
 * контракта возвращает предложение выбрать фракцию.
 */
function serverTerritoryGateArrival(leader = null, members = [], now = Date.now()) {
  const party = (Array.isArray(members) && members.length ? members : [leader]).filter(Boolean);
  const pending = party.filter(member => !territoryMembershipActive(member.territoryFaction));
  if (pending.length > 0) {
    const offer = serverTerritoryContractOffer(leader, now);
    offer.partyPending = pending.length;
    offer.partyPendingNames = pending.map(member => String(member.name || 'Игрок')).slice(0, 8);
    // Лидер с контрактом набирает спутников в свою фракцию, без контракта —
    // подписывает за всю группу выбранную фракцию.
    offer.canSign = offer.canSign || (territoryMembershipActive(leader?.territoryFaction) && pending.length > 0);
    return {
      ok: false,
      error: pending.some(member => member === leader)
        ? 'Контракт с фракцией не подписан: выберите фракцию на входе в Сердцевину.'
        : `Без контракта в Сердцевину не пускают: ${pending.map(member => member.name || 'Игрок').join(', ')}.`,
      contract: offer
    };
  }
  const baseLocationId = normalizeLocationId(
    territoryContractBaseLocationId(leader?.territoryFaction, KROMKA_TERRITORY_CATALOG)
  );
  if (!LOCATIONS[baseLocationId]) {
    return { ok: false, error: 'База фракции недоступна.', contract: serverTerritoryContractOffer(leader, now) };
  }
  return { ok: true, locationId: baseLocationId };
}

/** Портал в Сердцевину в её зоне мира — ворота территории. */
function serverTerritoryGatePortal() {
  const coreId = serverTerritoryZoneLocationId();
  const zoneId = ZONE_RUNTIME.parentZoneOf(coreId);
  const loc = zoneId ? ensureZoneLocation(zoneId) : null;
  const portal = (loc?.transitions || []).find(row => normalizeLocationId(row?.to || '') === coreId);
  return portal ? { zoneId, point: tileToWorld(Number(portal.tx), Number(portal.tz), locationTileDims(loc)) } : null;
}

/**
 * Контракт подписывают только у ворот: игрок в зоне Сердцевины у её портала.
 * Это исключает вступление из любой точки мира и оставляет регистратора базы
 * для смены и выхода.
 */
function serverPlayerAtTerritoryGate(player = null) {
  if (!player?.roomId || player.dead) return false;
  const gate = serverTerritoryGatePortal();
  if (!gate || normalizeLocationId(player.locationId || '') !== gate.zoneId) return false;
  return Math.hypot(Number(player.x || 0) - gate.point.x, Number(player.z || 0) - gate.point.z) <= 10;
}

/**
 * Спутники, подписывающие контракт вместе с лидером: товарищи по отряду рядом
 * с ним у ворот. Свою фракцию они не меняют: вступают только те, кто ещё не
 * подписал контракт.
 */
function serverTerritoryGateCompanions(leader = null) {
  if (!leader) return [];
  return serverWorldPartyMatesOnline(leader)
    .filter(member => member.roomId === leader.roomId && !territoryMembershipActive(member.territoryFaction)
      && Math.hypot(Number(member.x || 0) - Number(leader.x || 0), Number(member.z || 0) - Number(leader.z || 0)) <= ZONE_GATE_FOLLOW_METRES);
}

// Щит прибытия: 4 с после входа в зону через ворота игрока не задеть, пока он
// сам не выстрелит, — у ворот не караулят тех, кто ещё не видит, куда пришёл.
const ZONE_ARRIVAL_SHIELD_MS = 4000;
// Пауза ворот: 6 с после урона от игрока или по игроку ворота не пропускают —
// из перестрелки не уходят шагом в соседнюю зону.
const ZONE_GATE_PVP_PAUSE_MS = 6000;
// Отряд проходит ворота вслед за тем, кто шагнул первым, если стоит рядом.
const ZONE_GATE_FOLLOW_METRES = 8.5;

function serverZoneArrivalShielded(p = {}, now = Date.now()) {
  return Number(p?.zoneArrivalShieldUntil || 0) > now;
}

function serverZoneGatePvpPauseLeft(p = {}, now = Date.now()) {
  return Math.max(0, Number(p?.lastPvpAt || 0) + ZONE_GATE_PVP_PAUSE_MS - now);
}

function serverNotePvpExchange(attacker, target, now = Date.now()) {
  if (attacker) {
    attacker.lastPvpAt = now;
    attacker.zoneArrivalShieldUntil = 0;
  }
  if (target) target.lastPvpAt = now;
}

function serverPlayerCanDamagePlayer(attacker, target, room, now = Date.now()) {
  return locationAllowsPvp(roomLocation(room))
    && !serverZoneArrivalShielded(target, now)
    && !serverPlayersAllied(attacker, target)
    && !serverPlayerHasProtectedClanRally(target, room, now)
    && !serverTerritoryPvpBlock(attacker, target, room, now);
}

/**
 * Почему выстрел не нанёс урона. Правило сервер знает и так, но раньше
 * оставлял его себе: игрок тратил ОД и патрон, видел, что ничего не произошло,
 * и не понимал, запрет это или промах.
 */
function serverPvpBlockLabel(attacker = {}, target = {}, room = null, now = Date.now()) {
  if (!locationAllowsPvp(roomLocation(room))) return 'Здесь по игрокам не стреляют: мирная зона.';
  if (serverZoneArrivalShielded(target, now)) return 'Игрок только что вошёл в зону: несколько секунд его не задеть.';
  if (serverPlayersAllied(attacker, target)) return 'Это свой: по союзникам огонь не ведётся.';
  if (serverPlayerHasProtectedClanRally(target, room, now)) return 'Цель под защитой сбора клана.';
  switch (serverTerritoryPvpBlock(attacker, target, room, now)) {
    case 'sameFaction': return 'Контракт один на двоих: своих в Сердцевине не бьют.';
    case 'attackerOnPlatform': return 'С платформы фракции не стреляют.';
    case 'targetProtected': return 'Цель стоит на платформе своей фракции и вне боя: она защищена.';
    default: return '';
  }
}

/** То же для NPC: неприкосновенные новичковые, союзная фракция и свой отряд. */
function serverNpcBlockLabel(player = {}, enemy = null, room = null) {
  if (!enemy || enemy.dead) return '';
  if (!roomAllowsNpcCombat(room)) return 'Здесь драться нельзя.';
  if (serverNpcIsKromkaOnboardingProtected(enemy)) return 'Этого трогать нельзя: он под защитой Кромки.';
  if (!serverActorHostileToPlayer(enemy, player)) return 'Это не враг: он не станет отвечать.';
  if (serverCombatFactionsAllied(
    serverWorldFactionKey(player.worldFactionId || player.factionId || ''), enemy.faction
  )) return 'Это союзная фракция.';
  return 'Это свой в отряде.';
}

function serverProtectedAttackAck(player, spend, weapon, targetState = {}, protectedReason = '') {
  return {
    ok: true, protected: true, protectedReason: String(protectedReason || ''),
    hit: false, hits: [], damage: 0, killed: false,
    weapon: weapon.id, mode: spend.mode, fallback: !!spend.fallback,
    combat: spend.combat, combats: spend.combats,
    self: publicAuthoritativePlayerState(player), ...targetState
  };
}

