// ===== СИЛА: тиры экипировки =====
// Чистое железо: только предметы, их состояние и модификации. Очки тиров
// растут нелинейно, чтобы скачок тира ощущался; состояние входит множителем —
// сломанная броня роняет Силу на глазах.
const GEAR_ITEM_TIERS = Object.freeze({
  fists: 1, knife: 1, pickaxe: 1, axe: 1, handPump: 1, pistol: 1,
  rifle: 2, revolver: 2, sawedOffShotgun: 2,
  shotgun: 3, assaultRifle: 3, machineGun: 3, smg: 3,
  laserPistol: 4, flamethrower: 4,
  plasmaRifle: 5, rocketLauncher: 5,
  leather: 1, hazmatSuit: 1,
  metalArmor: 2, energySuit: 2,
  ballisticVest: 3,
  combatArmor: 4,
  heavyArmor: 5,
  weldedHelmet: 1, helmet: 2, tacticalHelmet: 3, assaultHelmet: 4, preWarHelmet: 5,
  boots: 1, scoutBoots: 2, reinforcedBoots: 3, assaultBoots: 4,
  backpack: 2
});
const GEAR_TIER_POINTS = Object.freeze({ 1: 10, 2: 18, 3: 30, 4: 45, 5: 65 });
const GEAR_SLOT_WEIGHTS = Object.freeze({ weapon: 1.0, offhand: 0.5, armor: 0.8, helmet: 0.4, boots: 0.3, backpack: 0.2 });
const GEAR_MOD_POINTS = 4;

function serverGearPower(p = {}) {
  let total = 0;
  for (const [slot, weight] of Object.entries(GEAR_SLOT_WEIGHTS)) {
    const equippedId = String(p.equipment?.[slot] || '');
    if (!equippedId) continue;
    const baseId = serverBaseItemId(equippedId);
    const tier = Number(GEAR_ITEM_TIERS[baseId] || 0);
    if (!tier) continue;
    const condition = Math.max(1, Math.min(100, Number(serverPlayerItemCondition(p, baseId) ?? 100)));
    total += GEAR_TIER_POINTS[tier] * weight * condition / 100;
    if (slot === 'weapon' || slot === 'offhand') {
      const mods = p.serverCombat?.weapons?.[equippedId]?.weaponMods || {};
      total += Object.values(mods).filter(Boolean).length * GEAR_MOD_POINTS;
    }
  }
  return Math.round(total);
}

const SERVER_ITEM_STACK_LIMITS = KROMKA_ITEM_INDEXES.stackLimits;

function serverItemStackLimit(itemId = '') {
  const id = serverBaseItemId(itemId);
  if (!id || id === 'fists' || !SERVER_ITEM_IDS.has(id)) return 0;
  return SERVER_ITEM_STACK_LIMITS[id] || 0;
}

function normalizeServerTraderStock(stock = []) {
  return (Array.isArray(stock) ? stock : [])
    .map(row => {
      const id = String(row?.id || '').trim();
      if (!SERVER_ITEM_IDS.has(id) || id === 'fists') return null;
      const qty = clamp(Math.floor(Number(row.qty ?? row.count ?? 1)), 1, serverItemStackLimit(id));
      const price = clamp(Math.round(Number(row.price ?? 1)), 1, 999999);
      const shelfTarget = clamp(Math.floor(Number(row.shelfTarget ?? qty)), 1, serverItemStackLimit(id));
      const shelfMin = clamp(Math.floor(Number(row.shelfMin ?? (shelfTarget <= 1 ? 0 : Math.max(1, Math.floor(shelfTarget * 0.3))))), 0, shelfTarget);
      const shelfMax = clamp(Math.floor(Number(row.shelfMax ?? Math.ceil(shelfTarget * 1.35))), shelfTarget, serverItemStackLimit(id));
      const priority = clamp(Math.round(Number(row.priority ?? 60)), 1, 100);
      return { id, qty: shelfTarget, price, shelfMin, shelfTarget, shelfMax, priority };
    })
    .filter(Boolean);
}

function normalizeServerTraderProfiles(raw = {}) {
  const src = raw && typeof raw === 'object' && raw.profiles && typeof raw.profiles === 'object'
    ? raw.profiles
    : raw;
  const out = {};
  for (const [profileId, profile] of Object.entries(src || {})) {
    if (!profile || typeof profile !== 'object') continue;
    const id = String(profile.id || profileId || '').trim().slice(0, 64);
    if (!id) continue;
    out[id] = {
      id,
      name: String(profile.name || id).slice(0, 80),
      dialogueProfile: String(profile.dialogueProfile || profile.dialogue || '').slice(0, 64),
      caps: clamp(Math.floor(Number(profile.caps ?? 0)), 0, 999999),
      restockHours: clamp(Math.floor(Number(profile.restockHours ?? 24)), 1, 720),
      buyInterests: (Array.isArray(profile.buyInterests) ? profile.buyInterests : [])
        .map(value => String(value || '').trim()).filter(Boolean).slice(0, 32),
      quests: (Array.isArray(profile.quests) ? profile.quests : [])
        .map(value => String(value || '').trim()).filter(Boolean).slice(0, 32),
      stock: normalizeServerTraderStock(profile.stock)
    };
  }
  return out;
}

function loadServerTraderProfiles() {
  return normalizeServerTraderProfiles(readAuthoredDataJson(TRADER_PROFILES_FILE, { profiles: {} }));
}

const SERVER_TRADER_PROFILES = loadServerTraderProfiles();

function normalizeServerNpcRoutines(raw = {}) {
  const source = raw && typeof raw === 'object' && raw.routines && typeof raw.routines === 'object'
    ? raw.routines
    : raw;
  const routines = {};
  for (const [routineId, row] of Object.entries(source || {})) {
    if (!row || typeof row !== 'object') continue;
    const id = String(row.id || routineId || '').trim().replace(/[^a-zA-Z0-9_:-]/g, '_').slice(0, 96);
    if (!id) continue;
    const routine = normalizeAuthoredRoutine(row, { id });
    if (!Array.isArray(routine.packages) || !routine.packages.length) continue;
    routines[id] = routine;
  }
  return routines;
}

