  const now = Date.now();
  enemy.aiState = 'return';
  enemy.targetId = '';
  enemy.investigateX = null;
  enemy.investigateZ = null;
  enemy.investigateStartedAt = 0;
  enemy.investigateUntil = 0;
  enemy.searchPoints = null;
  enemy.searchIndex = 0;
  enemy.searchPauseUntil = 0;
