  const gz = Number(goal?.z ?? enemy?.z ?? 0);
  const distance = Math.hypot(gx - Number(enemy?.x || 0), gz - Number(enemy?.z || 0));
  const speed = npcMeleeApproachSpeed(baseSpeed, distance);
