    if (!p || p.dead || Number(p.hp || 0) <= 0) return fail('Игрок недоступен.');
    const transaction = beginCriticalAction(p, 'socialStateAction', data, ['action', 'targetId', 'characterId', 'name']);
    if (!transaction.ok) return fail(transaction.error);
