    if (shotgunSpread && shotgunSpread.perp > shotgunSpread.width + shotgunSpread.targetRadius) return fail('Цель вне разлёта дроби.', spend.combat ? { combat: spend.combat } : {});
    const hitClientCombat = shotgunSpread
