let lastKromkaShiftRevision = '';
setInterval(() => {
  const now = Date.now();
  const globalShift = KROMKA_SHIFT_CYCLE.state(now);
  const revision = `${globalShift.shiftId}:${globalShift.phase}`;
  const phaseChanged = revision !== lastKromkaShiftRevision;
  lastKromkaShiftRevision = revision;
  if (phaseChanged && typeof WASTELAND_SIM.recordAnomalyShift === 'function') {
    try {
      WASTELAND_SIM.recordAnomalyShift(globalShift);
      invalidateWastelandPublicCache();
    } catch (err) {
      console.error('Anomaly Shift world simulation failed:', err);
    }
  }
  for (const room of rooms.values()) {
    const beforeShiftId = String(room.kromkaArtifactState?.shiftId || '');
    serverEnsureRoomArtifacts(room, now);
    if (beforeShiftId !== String(room.kromkaArtifactState?.shiftId || '')) room.worldStateDirty = true;
  }
  for (const p of players.values()) {
    if (!p || !p.roomId || p.onGlobalMap || p.dead) continue;
    const shift = serverCurrentShiftState(now, p);
    if (shift.phase === 'active' && !shift.sheltered && now - Number(p.lastShiftDamageAt || 0) >= 3000) {
      p.lastShiftDamageAt = now;
      const rawDamage = 4 + Number(shift.strength || 1) * 2;
      const mitigation = serverMitigateDamage(rawDamage, p, 'anomalous');
      p.hp = Math.max(0, Number(p.hp || p.maxHp || 1) - mitigation.damage);
      const newInjuries = serverApplyInjuriesFromHit(
        p,
        mitigation.damage,
        'anomalous',
        'Выброс'
      );
      p.lastServerDamageAt = now;
      const shiftRoom = rooms.get(p.roomId);
      const downed = Number(p.hp || 0) <= 0
        && serverTryDownWorldActivityPlayer(p, shiftRoom, now);
      io.to(p.id).emit('playerStatusEffect', {
        effect: 'shiftExposure',
        damage: mitigation.damage,
        rawDamage,
        absorbed: mitigation.absorbed,
        protection: Number((mitigation.protection * 100).toFixed(1)),
        resistance: Number((mitigation.resistance * 100).toFixed(1)),
        threshold: mitigation.threshold,
        strength: shift.strength,
        hp: Math.round(Number(p.hp || 0)),
        maxHp: Math.round(Number(p.maxHp || 1)),
        downed,
        injuries: sanitizeInjuries(p.injuries || {}),
        newInjuries,
        t: now
      });
      if (Number(p.hp || 0) <= 0) {
        p.dead = true;
        p.diedAt = now;
        const shiftLoc = shiftRoom ? roomLocation(shiftRoom) : null;
        const droppedItems = shiftRoom ? serverDropPvpLootForMode(shiftRoom, p, null, shiftLoc, now) : [];
        serverRespawnPlayer(p, shiftRoom, {
          shiftId: shift.shiftId,
          pvpMode: shiftLoc ? locationPvpMode(shiftLoc) : 'peaceful',
          fullDrop: !!shiftLoc && locationHasFullInventoryDrop(shiftLoc),
          droppedItems
        });
      }
    }
    if (phaseChanged || now - Number(p.lastArtifactStateAt || 0) >= 1000) {
      p.lastArtifactStateAt = now;
      emitServerArtifactState(p, phaseChanged ? 'shiftPhase' : 'proximity');
    }
  }
}, 500);

setInterval(() => {
  // 1) Сначала двигаем игроков.
  for (const p of players.values()) {
    const playerTickNow = Date.now();
    if (p.downed) {
      p.input = { forward: 0, right: 0 };
      p.vx = 0;
      p.vz = 0;
      p.moving = false;
      if (playerTickNow >= Number(p.downedUntil || 0)) {
        const downedRoom = rooms.get(String(p.roomId || '')) || null;
        if (downedRoom?.worldActivity) {
          setWorldActivityParticipantDowned(downedRoom.worldActivity, {
            socketId: p.id,
            userId: p.userId || '',
            characterId: p.characterId || '',
            downed: false,
            now: playerTickNow
          });
        }
        p.downed = false;
        p.downedUntil = 0;
        p.diedAt = playerTickNow;
        const bleedLoc = downedRoom ? roomLocation(downedRoom) : null;
        const bleedDrops = downedRoom ? serverDropPvpLootForMode(downedRoom, p, null, bleedLoc, playerTickNow) : [];
        serverRespawnPlayer(p, downedRoom, {
          bleedOut: true,
          pvpMode: bleedLoc ? locationPvpMode(bleedLoc) : 'peaceful',
          fullDrop: !!bleedLoc && locationHasFullInventoryDrop(bleedLoc),
          droppedItems: bleedDrops
        });
      }
      continue;
    }
    if (p.dead) continue;
    expireLegacyPlayerInput(p, playerTickNow);
    serverRegenPlayerAp(p, playerTickNow);
    repairImpossibleServerPlayerVitals(p, playerTickNow);
    updateServerPlayerMedicalEffects(p, playerTickNow);
    updateServerArtifactRegeneration(p, playerTickNow);
    const supportRoom = rooms.get(p.roomId);
    const supportEffects = serverArtifactEffects(p);
    tickArtifactRuntime(p, supportEffects, !!supportRoom && isWetEnvironment(p,
      ANOMALY_SYSTEM.authoredFields(supportRoom.locationId),
      (KROMKA_LOCATION_CATALOG.locations || []).find(row => row.id === supportRoom.locationId)?.wetZones || []), playerTickNow);
    if (isArtifactStunned(p, playerTickNow)) {
      p.input = { forward: 0, right: 0 }; p.vx = 0; p.vz = 0; p.moving = false;
    }
    const fwdX = Math.sin(p.angle);
    const fwdZ = Math.cos(p.angle);
    const rightX = Math.cos(p.angle);
    const rightZ = -Math.sin(p.angle);
    let dx = fwdX * p.input.forward + rightX * p.input.right;
    let dz = fwdZ * p.input.forward + rightZ * p.input.right;
    const len = Math.hypot(dx, dz) || 1;
    dx /= len; dz /= len;
    const moving = Math.abs(p.input.forward) + Math.abs(p.input.right) > 0.01;
    if (moving) {
      const speedFactor = (p.input.forward < -0.15 ? 0.58 : 1)
        * (1 + serverArtifactEffects(p).speedPct);
      const legacyExtent = playerWorldExtent(p);
      const nextX = clamp(p.x + dx * PLAYER_SPEED * speedFactor * DT, -legacyExtent, legacyExtent);
      const nextZ = clamp(p.z + dz * PLAYER_SPEED * speedFactor * DT, -legacyExtent, legacyExtent);
      const room = rooms.get(p.roomId);
      const closedBounds = serverClosedLocationMovementBounds(p, room, PLAYER_COLLISION_RADIUS);
      if (!room || (
        (!closedBounds || serverPointInsideClosedLocationBounds(nextX, nextZ, closedBounds))
        && isRoomTerrainWalkableWorld(room, nextX, nextZ, PLAYER_COLLISION_RADIUS)
        && roomStaticCollisionMoveAllowed(room, p.x, p.z, nextX, nextZ, PLAYER_COLLISION_RADIUS)
        && roomEnemyCollisionMoveAllowed(room, p.x, p.z, nextX, nextZ, PLAYER_COLLISION_RADIUS)
      )) {
        p.x = nextX;
        p.z = nextZ;
      }
    }

    const stepRadius = artifactFootstep(p, supportEffects, playerTickNow);
    if (stepRadius > 0) addRoomNoise(supportRoom, p.x, p.z, serverPlayerNoiseRadius(p, stepRadius), p.id, 'footstep');
    const anomalyRoom = rooms.get(p.roomId);
    const anomalyHit = anomalyRoom ? ANOMALY_SYSTEM.evaluatePlayer({
      roomId: anomalyRoom.id,
      locationId: anomalyRoom.locationId,
      playerId: p.id,
      x: p.x,
      z: p.z,
      now: playerTickNow
    }) : null;
    if (anomalyHit) {
      serverApplyDerivedVitals(p);
      const mitigation = serverMitigateDamage(anomalyHit.damage, p, anomalyHit.damageType);
      const secondChance = serverTrySecondChance(p, mitigation.damage, playerTickNow);
      if (!secondChance) p.hp = Math.max(0, Number(p.hp || p.maxHp) - mitigation.damage);
      const newInjuries = serverApplyInjuriesFromHit(
        p,
        mitigation.damage,
        anomalyHit.damageType,
        anomalyHit.anomalyName || 'Аномалия'
      );
      p.lastServerDamageAt = playerTickNow;
      serverApplyArtifactImpact(p, anomalyRoom, { x: anomalyHit.sourceX, z: anomalyHit.sourceZ },
        anomalyHit.damageType, anomalyHit.anomalyType === 'pull' ? -0.8 : anomalyHit.anomalyType === 'carousel' ? 0.8 : 0, playerTickNow);
      const downed = !secondChance && Number(p.hp || 0) <= 0
        && serverTryDownWorldActivityPlayer(p, anomalyRoom, playerTickNow);
      const killed = Number(p.hp || 0) <= 0 && !secondChance;
      const payload = {
        ...anomalyHit,
        playerId: p.id,
        characterId: p.characterId || '',
        targetName: p.name || 'Наёмник',
        rawDamage: anomalyHit.damage,
        damage: mitigation.damage,
        absorbed: mitigation.absorbed,
        protection: Number((mitigation.protection * 100).toFixed(1)),
        resistance: Number((mitigation.resistance * 100).toFixed(1)),
        threshold: mitigation.threshold,
        hp: Math.round(Number(p.hp || 0)),
        maxHp: Math.round(Number(p.maxHp || 100)),
        secondChance,
        downed,
        killed,
        injuries: sanitizeInjuries(p.injuries || {}),
        newInjuries
      };
      io.to(anomalyRoom.id).emit('playerDamaged', payload);
      io.to(p.id).emit('playerStatusEffect', payload);
      if (killed) {
        p.dead = true;
        p.diedAt = playerTickNow;
        const anomalyLoc = roomLocation(anomalyRoom);
        const droppedItems = serverDropPvpLootForMode(anomalyRoom, p, null, anomalyLoc, playerTickNow);
        serverRespawnPlayer(p, anomalyRoom, {
          anomalyId: anomalyHit.anomalyId,
          anomalyName: anomalyHit.anomalyName,
          pvpMode: locationPvpMode(anomalyLoc),
          fullDrop: locationHasFullInventoryDrop(anomalyLoc),
          droppedItems
        });
      }
    }
  }

  // 2) Потом серверный AI мобов. Здесь игрок может умереть и сменить комнату.
  // Поэтому snapshots игроков собираем только после этого шага, иначе старый room
  // может повторно добавить модель умершего игрока после события playerLeft.
  let activeRoomAiBudget = 1;
  let emptyRoomAiBudget = 1;
  for (const room of rooms.values()) {
    const beforeCleanupSize = room.sockets.size;
    for (const sid of [...room.sockets]) if (!socketIsLive(sid)) room.sockets.delete(sid);
    if (beforeCleanupSize > 0 && room.sockets.size === 0) markRoomEmptyIfNeeded(room, 'staleSocketCleanup');
    const roomNow = Date.now();
    if (room.sockets.size > 0) updateServerWorldActivity(room, roomNow);
    if (room.sockets.size > 0) {
      room.emptyRoomAiUntil = 0;
      room.lastEmptyAiTickAt = roomNow;
      const previousActiveAiTickAt = Number(room.lastActiveEnemyAiTickAt || roomNow - ACTIVE_ROOM_AI_TICK_MS);
      const activeAiElapsedMs = Math.max(0, roomNow - previousActiveAiTickAt);
      if (activeRoomAiBudget > 0 && activeAiElapsedMs >= ACTIVE_ROOM_AI_TICK_MS) {
        activeRoomAiBudget -= 1;
        room.lastActiveEnemyAiTickAt = roomNow;
        const enemyDt = Math.min(ACTIVE_ROOM_AI_MAX_DT, Math.max(DT, activeAiElapsedMs / 1000));
        const enemyStructureChanged = updateServerEnemies(room, enemyDt);
        syncWorldBattleRoomActors(room);
        emitEnemySnapshot(room, enemyStructureChanged);
      }
      if (roomNow - Number(room.lastActiveHousekeepingAt || 0) >= ACTIVE_ROOM_HOUSEKEEPING_MS) {
        room.lastActiveHousekeepingAt = roomNow;
        if (restockRoomWorldContainersIfNeeded(room)) {
          // Ящики обновились по игровым суткам; снимок уже отправлен внутри функции.
        }
        if (cleanupGroundItems(room)) {
          refreshRoomWorldState(room);
          emitGroundItemsSnapshot(room, true);
        }
        if (updateRoomResourceRespawns(room, roomNow)) {
          io.to(room.id).emit('worldState', { reason: 'resourceRespawn', state: currentRoomWorldState(room) });
        }
      }
    } else if (room.worldReady && roomNow - Number(room.lastEmptyAiTickAt || 0) >= EMPTY_ROOM_AI_TICK_MS) {
      if (!shouldTickEmptyRoomAi(room, roomNow)) {
        room.lastEmptyAiTickAt = roomNow;
        continue;
      }
      if (emptyRoomAiBudget <= 0) continue;
      emptyRoomAiBudget -= 1;
      const previousTickAt = Number(room.lastEmptyAiTickAt || roomNow - EMPTY_ROOM_AI_TICK_MS);
      const elapsed = Math.max(0, (roomNow - previousTickAt) / 1000);
      room.lastEmptyAiTickAt = roomNow;
      const dt = Math.min(EMPTY_ROOM_AI_MAX_DT, elapsed || DT);
      updateServerEnemies(room, dt, { players: [], allowSpawn: false });
      syncWorldBattleRoomActors(room);
      restockRoomWorldContainersIfNeeded(room);
      if (cleanupGroundItems(room, roomNow)) refreshRoomWorldState(room);
      updateRoomResourceRespawns(room, roomNow);
    }
  }

  // 3) Финальный актуальный snapshot по комнатам после всех смертей/респавнов.
  const byRoom = new Map();
  for (const p of players.values()) {
    if (!p.roomId || !socketIsLive(p.id)) continue;
    // Мёртвый игрок не должен снова попасть в полный snapshot старой комнаты
    // между событием смерти и респавном. Иначе клиент может заново создать старую модель.
    if ((p.dead && !p.downed) || Number(p.hp || 0) <= 0) continue;
    if (!byRoom.has(p.roomId)) byRoom.set(p.roomId, []);
    byRoom.get(p.roomId).push(p);
  }
  const snapshotNow = Date.now();
  for (const [roomId, roomPlayers] of byRoom.entries()) {
    const room = rooms.get(roomId);
    if (!room) continue;
    // v7.74.55: the full player snapshot is no longer the movement stream.
    // playerState carries motion immediately; snapshot only reconciles room
    // membership/status. Throttling it removes small CPU/GC spikes on mobile and
    // prevents a second stream from fighting remote-player smoothing.
    if (snapshotNow - Number(room.lastPlayerSnapshotAt || 0) < 1000) continue;
    room.lastPlayerSnapshotAt = snapshotNow;
    const list = roomPlayers.map(publicPlayer);
    io.to(roomId).volatile.emit('snapshot', { roomId, locationId: room?.locationId || '', t: snapshotNow, players: list });
  }
}, 1000 / TICK_RATE);

function getLanUrls(port) {
  const urls = [];
  const nets = os.networkInterfaces();
  for (const list of Object.values(nets)) {
    for (const net of list || []) {
      if (net.family === 'IPv4' && !net.internal) urls.push(`http://${net.address}:${port}`);
    }
  }
  return urls;
}

server.listen(PORT, '0.0.0.0', () => {
  const address = server.address();
  const boundPort = address && typeof address === 'object'
    ? Number(address.port || PORT)
    : PORT;
  if (!configuredOrigins && boundPort !== PORT) {
    allowedOrigins.splice(
      0,
      allowedOrigins.length,
      ...defaultLocalServerOrigins(boundPort).split(',').filter(Boolean)
    );
  }
  console.log(`${GAME_NAME} v${GAME_VERSION} server listening on :${boundPort}`);
  console.log(`Dev API mode: ${DEV_ACCESS_POLICY.mode}`);
  console.log(`Local: http://localhost:${boundPort}`);
  const lanUrls = getLanUrls(boundPort);
  if (lanUrls.length) console.log(`LAN: ${lanUrls.join('  |  ')}`);
  console.log(`Data directory: ${DATA_DIR}`);
});
